// ---------- utilidades ----------

const _norm = (s) =>
  (s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const _tokens = (s) => _norm(s).split(/[^a-z0-9]+/).filter(Boolean);

/**
 * Un campo "coincide" si TODOS los tokens de la consulta aparecen como
 * prefijo de alguna palabra del campo. Evita falsos positivos por subcadena
 * (p. ej. 'PTI' dentro de 'optico') y permite orden libre de palabras
 * ('linfoma del manto' encuentra 'linfoma de celulas del manto').
 */
const _coincide = (campo, qt) => {
  const ct = _tokens(campo);
  return qt.every((q) => ct.some((c) => c.startsWith(q)));
};

/** Índice por código: acepta 'C83.1' y 'C831'. */
export const CIE10_INDEX = CIE10.reduce((acc, i) => {
  acc[i.codigo] = i;
  acc[i.codigoRips] = i;
  return acc;
}, {});

/**
 * Busca por código o por texto. El texto se compara contra la descripción
 * oficial Y contra los sinónimos clínicos actuales, de modo que
 * 'linfoma del manto' encuentra C83.1 aunque la etiqueta oficial de 2001
 * no use ese término.
 */
export function buscarCIE10(termino, { grupo, limite = 50 } = {}) {
  const t = _norm(termino).trim();
  if (!t) return [];
  const qt = _tokens(t);
  const qcod = t.replace(/[^a-z0-9]/g, '');
  const esCodigo = /^[a-z]\d{2}/.test(qcod);
  const base = grupo ? CIE10.filter((i) => i.grupo === grupo) : CIE10;

  const puntaje = (i) => {
    const cod = i.codigoRips.toLowerCase();
    if (esCodigo) {
      if (cod === qcod) return 0;
      if (cod.startsWith(qcod)) return 1;
    }
    const sin = i.sinonimos || [];
    if (sin.some((s) => _norm(s).trim() === t)) return 2;      // sinónimo exacto
    if (_norm(i.descripcion).startsWith(t)) return 3;
    if (sin.some((s) => _coincide(s, qt))) return 4;           // sinónimo por tokens
    if (_coincide(i.descripcion, qt)) return 5;                // descripción por tokens
    return 99;
  };

  return base
    .map((i) => ({ item: i, p: puntaje(i) }))
    .filter((x) => x.p < 99)
    .sort((a, b) => a.p - b.p || a.item.codigo.localeCompare(b.item.codigo))
    .slice(0, limite)
    .map((x) => x.item);
}

export const porGrupo = (g) => CIE10.filter((i) => i.grupo === g);
export const porSubgrupo = (s) => CIE10.filter((i) => i.subgrupo === s);
export const esMaligno = (c) => /^C/i.test(c);

/** Códigos cuya etiqueta oficial difiere de la entidad clínica actual. */
export const CON_ALERTA = CIE10.filter((i) => i.alerta);

export default CIE10;
